import { create } from 'zustand'

export type FilterConfig<T extends string = string> = {
	id: T
	title: string
}

export interface FilterState<T extends string = string> {
	filters: T[]
	hasFilter: (filter: T) => boolean
	toggleFilter: (filter: T) => void
	filtersCount: number
}

export function createFilterStore<T extends string = string>() {
	return create<FilterState<T>>((set, get) => ({
		filters: [],
		hasFilter: (filter: T) => get().filters.includes(filter),
		toggleFilter: (newFilter: T) => {
			const filters = get().filters
			const newFilters = filters.includes(newFilter)
				? filters.filter((filter) => newFilter !== filter)
				: [...filters, newFilter]
			set({
				filters: newFilters,
				filtersCount: newFilters.length,
				hasFilter: (filter: T) => newFilters.includes(filter)
			})
		},
		filtersCount: 0
	}))
}
